func gtLoops(pa *port.Cells, pts *port.Cells, page int32, x0 int32, y0 int32, segs int32, step int32, high int32) int32 {
	// An open stroked curve of `segs` Bezier segments from (x0, y0), `step` wide each and `high` high, looping up and down (a pen's); 140 wide; blue; answers its row.
	var first int32 = port.CellsLen(pts) / 3
	var k int32 = 0
	var r int32 = evidence.PaNew(pa, page, evidence.PaCurve(), x0, y0, x0+(segs*step), y0+high)
	evidence.PtAdd(pts, x0, y0, evidence.PoMove())
	for k < segs {
		evidence.PtAdd(pts, x0+(k*step), y0+high, evidence.PoCurve())
		evidence.PtAdd(pts, x0+((k*step)+(step/2)), y0, evidence.PoCurve())
		evidence.PtAdd(pts, x0+((k+1)*step), y0+((high*5)/10), evidence.PoCurve())
		k += 1
	}
	evidence.PaSet(pa, r, evidence.PfFlags(), evidence.PgStroked())
	evidence.PaSet(pa, r, evidence.PfStroke(), 2047903)
	evidence.PaSet(pa, r, evidence.PfWidth(), 140)
	evidence.PaSet(pa, r, evidence.PfPfirst(), first)
	evidence.PaSet(pa, r, evidence.PfPcount(), 1+(segs*3))
	return r
}

func gtFlat(pa *port.Cells, pts *port.Cells, page int32, x0 int32, y0 int32, segs int32, step int32) int32 {
	// An open stroked curve of `segs` Bezier segments that runs straight to the right (every control point on the line): no loops at all.
	var first int32 = port.CellsLen(pts) / 3
	var k int32 = 0
	var r int32 = evidence.PaNew(pa, page, evidence.PaCurve(), x0, y0, x0+(segs*step), y0+10)
	evidence.PtAdd(pts, x0, y0, evidence.PoMove())
	for k < segs {
		evidence.PtAdd(pts, x0+((k*step)+(step/3)), y0, evidence.PoCurve())
		evidence.PtAdd(pts, x0+((k*step)+((step*2)/3)), y0, evidence.PoCurve())
		evidence.PtAdd(pts, x0+((k+1)*step), y0, evidence.PoCurve())
		k += 1
	}
	evidence.PaSet(pa, r, evidence.PfFlags(), evidence.PgStroked())
	evidence.PaSet(pa, r, evidence.PfStroke(), 2047903)
	evidence.PaSet(pa, r, evidence.PfWidth(), 140)
	evidence.PaSet(pa, r, evidence.PfPfirst(), first)
	evidence.PaSet(pa, r, evidence.PfPcount(), 1+(segs*3))
	return r
}

func gtRule(pa *port.Cells, pts *port.Cells, page int32, x0 int32, x1 int32, y int32) int32 {
	// A straight stroked line from (x0, y) to (x1, y), 80 wide, gray.
	var first int32 = port.CellsLen(pts) / 3
	var r int32 = evidence.PaNew(pa, page, evidence.PaLine(), x0, y, x1, y)
	evidence.PtAdd(pts, x0, y, evidence.PoMove())
	evidence.PtAdd(pts, x1, y, evidence.PoLine())
	evidence.PaSet(pa, r, evidence.PfFlags(), evidence.PgStroked())
	evidence.PaSet(pa, r, evidence.PfStroke(), 6316128)
	evidence.PaSet(pa, r, evidence.PfWidth(), 80)
	evidence.PaSet(pa, r, evidence.PfPfirst(), first)
	evidence.PaSet(pa, r, evidence.PfPcount(), 2)
	return r
}

func gtWord(fw *port.Cells, et *port.Cells, page int32, x int32, y int32, b []byte) int32 {
	// A text-layer word of the bytes of `b` with its box 1100 high and 600 wide a letter, its top-left corner at (x, y); answers its row.
	var ts int32 = port.CellsLen(et)
	var n int32 = port.BlobLen(b)
	var k int32 = 0
	var w int32 = evidence.WdNew(fw, page, x, y, x+(n*600), y+1100, x, y+900, x+(n*600), y+900, 0, 0, ts, n, 0, -1, -1)
	for k < n {
		port.CellsPush(et, port.BlobU8(b, k))
		k += 1
	}
	return w
}

func gtOword(ow *port.Cells, et *port.Cells, page int32, x int32, y int32, b []byte, conf int32) int32 {
	// An OCR word of page `page` with its box 1100 high and 600 wide a letter, its top-left corner at (x, y), the engine's confidence `conf`; answers its row.
	var ts int32 = port.CellsLen(et)
	var n int32 = port.BlobLen(b)
	var k int32 = 0
	var r int32 = evidence.OwNew(ow, page, x, y, x+(n*600), y+1100, x, y+900, x+(n*600), y+900, 0, 0, ts, n, 0, conf, -1)
	for k < n {
		port.CellsPush(et, port.BlobU8(b, k))
		k += 1
	}
	return r
}

func gtFind(pa *port.Cells, pts *port.Cells, fw *port.Cells, et *port.Cells, ow *port.Cells, an *port.Cells, txt *port.Cells, np int32, sm *port.Cells) int32 {
	// `sm-find` over `np` pages of 612 x 792 pt, with no correspondence group.
	var ep *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var scr *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var sgc *port.Cells = port.NewCells()
	var p int32 = 1
	for p <= np {
		evidence.EpNew(ep, p, 61200, 79200)
		p += 1
	}
	return sealmark.SmFind(pa, pts, gl, fw, et, ep, cg, refs, ow, an, txt, np, sm, scr, tmp, sgc)
}

