func gtText(txt *port.Cells, b []byte) int32 {
	// Append the bytes of `b` to `txt` as code points; answers the run's start.
	var s int32 = port.CellsLen(txt)
	var n int32 = port.BlobLen(b)
	var k int32 = 0
	for k < n {
		port.CellsPush(txt, port.BlobU8(b, k))
		k += 1
	}
	return s
}

func gtDigsig(an *port.Cells, txt *port.Cells, page int32, y int32, bits int32, year int32, mlen int32) int32 {
	// A synthetic row of P3.8 for a signature field on page `page` (0-based), its rectangle at y: /Name `Zed Fox`, /Reason `ok`, /Location `Rome`, the signing time year-04-01 08:09:10 UTC when year >= 0.
	var at int32 = port.CellsLen(an)
	var k int32 = 0
	for k < 38 {
		port.CellsPush(an, 0)
		k += 1
	}
	port.CellsSet(an, at, page)
	port.CellsSet(an, at+1, pdfannot.AnDigsig())
	port.CellsSet(an, at+4, 19000)
	port.CellsSet(an, at+5, y)
	port.CellsSet(an, at+6, 40000)
	port.CellsSet(an, at+7, y+3400)
	k = 8
	for k < 15 {
		port.CellsSet(an, at+k, -1)
		k += 1
	}
	if year >= 0 {
		port.CellsSet(an, at+8, year)
		port.CellsSet(an, at+9, 4)
		port.CellsSet(an, at+10, 1)
		port.CellsSet(an, at+11, 8)
		port.CellsSet(an, at+12, 9)
		port.CellsSet(an, at+13, 10)
		port.CellsSet(an, at+14, 0)
	}
	port.CellsSet(an, at+15, mlen)
	port.CellsSet(an, at+23, -1)
	port.CellsSet(an, at+24, 0)
	port.CellsSet(an, at+27, -1)
	port.CellsSet(an, at+28, 0)
	port.CellsSet(an, at+32, -1)
	port.CellsSet(an, at+33, 0)
	port.CellsSet(an, at+34, -1)
	port.CellsSet(an, at+35, 0)
	port.CellsSet(an, at+30, bits)
	if bits > 0 {
		port.CellsSet(an, at+23, gtText(txt, port.TextBlob("Zed Fox")))
		port.CellsSet(an, at+24, 7)
		port.CellsSet(an, at+27, gtText(txt, port.TextBlob("ok")))
		port.CellsSet(an, at+28, 2)
		port.CellsSet(an, at+32, gtText(txt, port.TextBlob("Rome")))
		port.CellsSet(an, at+33, 4)
	}
	return at / 38
}

func TestADigitalSignatureFieldIsACandidateWhetherSignedOrNot(emonT *testing.T) {
	var pa *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var sm *port.Cells = port.NewCells()
	port.AssertEq(emonT, sigmark.SgHasDigital(an), 0, "no row, no digital signature")
	gtDigsig(an, txt, 0, 30000, 3, 2026, 16)
	gtDigsig(an, txt, 0, 50000, 0, -1, 0)
	port.AssertEq(emonT, sigmark.SgHasDigital(an), 1, "a row of the subtype")
	port.AssertEq(emonT, gtFind(pa, pts, fw, et, ow, an, txt, 1, sm), 2, "a signed field and an unsigned one, on a page with no path at all")
	port.AssertEq(emonT, player.SlGet(sm, 0, 5), player.PlsDigitalSignature(), "a digital signature")
	port.AssertEq(emonT, player.SlGet(sm, 0, 1), 19000, "its box is the widget's")
	port.AssertEq(emonT, player.SlGet(sm, 0, 12)&256, 256, "the text run is a record (flag 256)")
	port.AssertEq(emonT, player.SlGet(sm, 0, 12)&512, 512, "signed (flag 512)")
	port.AssertEq(emonT, player.SlGet(sm, 0, 7), -1, "it points at no path")
	port.AssertEq(emonT, player.SlGet(sm, 0, 15), -1, "and has no ink")
	port.AssertEq(emonT, player.SlGet(sm, 0, 9), 951, "a signed field is as sure as the file says")
	port.AssertEq(emonT, player.SlGet(sm, 1, 12)&512, 0, "the second is not signed")
	port.AssertEq(emonT, player.SlGet(sm, 1, 9), 900, "and a little less sure")
	port.AssertEq(emonT, player.SlGet(sm, 1, 14), 3, "its record is only the three separators")
	// the record of the first: Zed Fox US ok US Rome US 2026-04-01T08:09:10Z
	port.AssertEq(emonT, player.SlGet(sm, 0, 14), 36, "7 + 1 + 2 + 1 + 4 + 1 + 20 characters")
	port.AssertEq(emonT, port.CellsAt(et, player.SlGet(sm, 0, 13)+7), 31, "the separator after the name")
}

func TestTheModelCarriesTheDigitalSignature(emonT *testing.T) {
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var chk *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var fw *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var sm *port.Cells = port.NewCells()
	var nn *port.Cells = port.NewCells()
	var na *port.Cells = port.NewCells()
	var nr *port.Cells = port.NewCells()
	var nm *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	var sec int32 = model.NodeNew(nodes, model.NkSection(), 0)
	var par int32 = model.NodeNew(nodes, model.NkParagraph(), sec)
	model.NodeAddRegion(nodes, regions, par, 1, 10000, 10000, 60000, 20000)
	gtDigsig(an, txt, 0, 30000, 3, 2026, 16)
	gtDigsig(an, txt, 0, 50000, 0, -1, 0)
	port.AssertEq(emonT, gtFind(pa, pts, fw, et, ow, an, txt, 1, sm), 2, "two candidates")
	port.AssertEq(emonT, sealmark.SmWrite(sm, et, nodes, attrs, regions, text, nn, na, nr, nm), 2, "two nodes written")
	port.AssertEq(emonT, model.NodeKind(nn, 3), model.NkSeal(), "the first seal node")
	port.AssertEq(emonT, model.NodeSub(nn, 3), model.SlDigitalSignature(), "of the subkind digital-signature")
	var a int32 = model.NodeAttr(nn, na, 3, model.FkName())
	var d int32 = model.NodeAttr(nn, na, 3, model.FkDate())
	var r int32 = model.NodeAttr(nn, na, 3, model.FkReason())
	var l int32 = model.NodeAttr(nn, na, 3, model.FkLocation())
	var s int32 = model.NodeAttr(nn, na, 3, model.FkSigned())
	var u int32 = model.NodeAttr(nn, na, 4, model.FkSigned())
	var un int32 = model.NodeAttr(nn, na, 4, model.FkName())
	port.AssertEq(emonT, model.AttrLen(na, a), 7, "the signer, Zed Fox")
	port.AssertEq(emonT, port.CellsAt(text, model.AttrValue(na, a)), 90, "which starts with Z")
	port.AssertEq(emonT, model.AttrLen(na, r), 2, "the reason, ok")
	port.AssertEq(emonT, model.AttrLen(na, l), 4, "the location, Rome")
	port.AssertEq(emonT, model.AttrLen(na, d), 20, "the time as ISO 8601 with its zone")
	port.AssertEq(emonT, port.CellsAt(text, model.AttrValue(na, d)+19), 90, "ending in Z for UTC")
	port.AssertEq(emonT, port.CellsAt(text, model.AttrValue(na, d)+10), 84, "with a T between the day and the hour")
	port.AssertEq(emonT, model.AttrValue(na, s), 1, "signed")
	port.AssertEq(emonT, model.AttrValue(na, u), 0, "the second is not")
	port.AssertEq(emonT, model.NodeAttr(nn, na, 4, model.FkDate()), -1, "and says no date")
	port.AssertEq(emonT, un, -1, "or name")
	port.AssertEq(emonT, model.ModelCheck(nn, na, nr, text, pages, ledger, layout, chk), 0, "and the Model still checks")
}
